(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const r of document.querySelectorAll('link[rel="modulepreload"]'))n(r);new MutationObserver(r=>{for(const s of r)if(s.type==="childList")for(const a of s.addedNodes)a.tagName==="LINK"&&a.rel==="modulepreload"&&n(a)}).observe(document,{childList:!0,subtree:!0});function t(r){const s={};return r.integrity&&(s.integrity=r.integrity),r.referrerPolicy&&(s.referrerPolicy=r.referrerPolicy),r.crossOrigin==="use-credentials"?s.credentials="include":r.crossOrigin==="anonymous"?s.credentials="omit":s.credentials="same-origin",s}function n(r){if(r.ep)return;r.ep=!0;const s=t(r);fetch(r.href,s)}})();const rn=[{zh:"极早期宇宙",en:"The primordial universe",age:"约 10⁻⁴³ 秒",ageEn:"~10⁻⁴³ seconds",tag:"THE EDGE OF THE KNOWN",scale:"量子尺度 / QUANTUM",temp:"极端高温",zhText:"在我们能够追溯的最早时刻，宇宙处于极热、极密的状态，空间本身正在演化。",enText:"At the edge of what we can describe, the universe is extremely hot and dense. Space itself evolves.",zhVoice:"让我们回到时间的深处。这里没有爆炸的中心，也没有宇宙之外的空旷舞台。我们所能追溯的早期宇宙，处处极热、极密。更早发生了什么，仍是未知。",enVoice:"Travel to the edge of known time. There is no central explosion, and no empty stage outside the universe. The early cosmos is hot and dense everywhere. What happened earlier remains unknown.",note:"普朗克时期是现有理论的边界；画面为概念示意，并非对宇宙起点的观测。",noteEn:"The Planck era marks a limit of current theory. This is a conceptual view, not an observation of the origin."},{zh:"暴胀时期",en:"Cosmic inflation",age:"约 10⁻³⁶–10⁻³² 秒",ageEn:"~10⁻³⁶–10⁻³² seconds",tag:"SPACE ITSELF EXPANDS",scale:"空间膨胀 / EXPANSION",temp:"快速演化",zhText:"在暴胀模型中，空间经历极其迅速的近指数膨胀，微小涨落被拉伸到巨大尺度。",enText:"In inflationary models, space expands almost exponentially, stretching tiny fluctuations to immense scales.",zhVoice:"想象空间中每一段距离，都在同时被拉长。这不是物质向外炸开，而是空间本身迅速膨胀。微小的量子涨落，可能就这样成为未来宇宙结构的种子。",enVoice:"Imagine distances throughout space stretching together. Matter is not exploding outward. Space itself expands rapidly. Tiny quantum fluctuations may become the seeds of future cosmic structure.",note:"暴胀是解释观测的理论框架，具体机制与起止时间尚不确定。网格没有物理中心或边界。",noteEn:"Inflation is a theoretical framework; its mechanism and timing remain uncertain. The grid has no physical center or edge."},{zh:"基本粒子形成",en:"A sea of particles",age:"约 10⁻¹²–10⁻⁶ 秒",ageEn:"~10⁻¹²–10⁻⁶ seconds",tag:"ENERGY BECOMES MATTER",scale:"亚原子尺度 / SUBATOMIC",temp:"约 10¹⁵–10¹² K",zhText:"暴胀结束后的再加热使宇宙充满粒子与辐射；冷却中的夸克、胶子和轻子不断相互作用。",enText:"Reheating fills the universe with particles and radiation. Quarks, gluons and leptons interact as it cools.",zhVoice:"暴胀结束后，能量转化为炽热的粒子与辐射。夸克、胶子和电子等粒子，构成沸腾的海洋。空间继续膨胀，温度逐渐降低。",enVoice:"After inflation, energy becomes a hot bath of particles and radiation. Quarks, gluons and electrons fill the cosmos. As space expands, this restless sea gradually cools.",note:"粒子颜色仅用于区分种类；此时还没有原子、恒星或星系。",noteEn:"Colors distinguish particle types. Atoms, stars and galaxies do not yet exist."},{zh:"质子与中子出现",en:"Protons & neutrons",age:"约 10⁻⁶ 秒起",ageEn:"From ~10⁻⁶ seconds",tag:"THE BUILDING BLOCKS",scale:"约 10⁻¹⁵ m / NUCLEON",temp:"约 10¹² K",zhText:"随着宇宙冷却，夸克被束缚在强相互作用形成的复合粒子中，包括质子和中子。",enText:"As the universe cools, the strong interaction binds quarks into composite particles, including protons and neutrons.",zhVoice:"大约百万分之一秒之后，夸克被束缚在一起，形成质子和中子。它们将成为原子核的组成部分。但宇宙仍然太热，还无法留住完整的原子。",enVoice:"Around a millionth of a second later, quarks become bound into protons and neutrons. These will build atomic nuclei. The universe is still far too hot for complete atoms.",note:"三粒子组合是简化示意，真实核子还包含胶子与不断变化的夸克海。",noteEn:"Three-particle groups are simplified. Real nucleons also contain gluons and a changing sea of quarks."},{zh:"原初核合成",en:"Primordial nucleosynthesis",age:"约 3–20 分钟",ageEn:"~3–20 minutes",tag:"THE FIRST NUCLEI",scale:"原子核尺度 / NUCLEI",temp:"约 10⁹ K",zhText:"质子和中子结合，形成氘、氦与微量锂的原子核；大量质子保留下来，成为氢核。",enText:"Protons and neutrons build deuterium, helium and traces of lithium nuclei. Many protons remain as hydrogen nuclei.",zhVoice:"宇宙诞生几分钟后，质子与中子终于能组成轻元素的原子核。氢和氦，成为普通物质的主角。继续冷却的宇宙，很快关上了这座最早的核反应炉。",enVoice:"Within minutes, protons and neutrons can assemble into light nuclei. Hydrogen and helium dominate ordinary matter. Continued cooling soon closes this first cosmic nuclear furnace.",note:"原初核合成形成的是原子核；中性原子要等到约38万年后。",noteEn:"Nucleosynthesis makes nuclei. Neutral atoms form much later, around 380,000 years."},{zh:"中性原子形成",en:"The first neutral atoms",age:"约 38 万年",ageEn:"~380,000 years",tag:"THE COSMIC FOG CLEARS",scale:"原子尺度 / ATOMIC",temp:"约 3,000 K",zhText:"电子与原子核结合，形成以氢为主的中性原子，自由电子减少，宇宙逐渐变得透明。",enText:"Electrons join nuclei to form neutral atoms, mostly hydrogen. With fewer free electrons, the universe becomes transparent.",zhVoice:"三十八万年后，温度降到约三千开尔文。电子能够与原子核结合。随着自由电子减少，反复散射光的迷雾散去，光终于可以穿越遥远的空间。",enVoice:"After 380,000 years, the temperature falls to about three thousand kelvin. Electrons join nuclei. With fewer free electrons to scatter light, the cosmic fog clears.",note:"电子云为概率分布的示意，电子并不沿经典行星轨道绕核运行。",noteEn:"Electron clouds represent probability distributions, not planetary orbits around a nucleus."},{zh:"宇宙的第一缕余光",en:"The cosmic microwave background",age:"约 38 万年",ageEn:"~380,000 years",tag:"AN ECHO THAT STILL REACHES US",scale:"大尺度辐射场 / RADIATION",temp:"当时约 3,000 K",zhText:"与中性原子形成几乎同时，原有光子不再频繁散射；这份古老余辉今天被红移为微波背景。",enText:"Alongside recombination, existing photons stop scattering frequently. Expansion redshifts this ancient light into today’s microwave background.",zhVoice:"这不是新点燃的一道闪光，而是早已存在的光子，终于开始自由远行。空间的膨胀拉长了它们的波长。今天，我们仍能在各个方向接收到这份微波余辉。",enVoice:"This is not a newly ignited flash. Existing photons can finally travel freely. Expanding space stretches their wavelengths. Today we receive this microwave afterglow from every direction.",note:"与上一章属于同一时代，分章是为了分别解释物质与光。色差为放大的温度起伏示意。",noteEn:"This overlaps the previous chapter in time. Colors exaggerate tiny temperature fluctuations; this is not a measured sky map."},{zh:"宇宙黑暗时代",en:"The cosmic dark ages",age:"约 38 万–1 亿年",ageEn:"~380,000–100 million years",tag:"BEFORE THE FIRST STAR",scale:"气体云尺度 / GAS CLOUDS",temp:"持续冷却",zhText:"恒星尚未点亮。氢氦气体在暗物质的引力作用下，缓慢汇入更稠密的区域。",enText:"No stars shine yet. Under gravity, hydrogen and helium slowly gather in denser regions shaped by dark matter.",zhVoice:"漫长的黑暗开始了。没有恒星，也没有星系的灯火。但引力从未停息。气体沿着暗物质塑造的结构聚集，静静地孕育第一代恒星。",enVoice:"A long darkness begins. There are no stars to light it. Yet gravity never rests. Gas gathers within structures shaped by dark matter, preparing the birth of the first stars.",note:"微弱光点代表气体密度采样，不是恒星；暗物质和气体结构以可见颜色示意。",noteEn:"Faint points sample gas density, not stars. Dark matter and gas structure are shown in illustrative colors."},{zh:"第一批恒星点亮",en:"The first light",age:"约 1–2 亿年",ageEn:"~100–200 million years",tag:"THE COSMIC DAWN",scale:"恒星与气体云 / STELLAR",temp:"星核可达数千万 K",zhText:"致密气体坍缩，核心启动核聚变，第一批恒星照亮宇宙，并逐步电离周围的氢气。",enText:"Dense gas collapses until fusion ignites. The first stars light the universe and begin ionizing the surrounding hydrogen.",zhVoice:"在最稠密的气体云中，引力点燃核聚变。第一批恒星，终于照亮宇宙。它们的紫外光开始改变周围的气体，为宇宙的黎明揭开帷幕。",enVoice:"Inside dense clouds, gravity brings gas to the heat of nuclear fusion. The first stars ignite. Their ultraviolet light begins to transform surrounding gas. Cosmic dawn has arrived.",note:"第一批恒星的确切诞生时间仍不确定；1–2亿年是常见模型估计。",noteEn:"The exact timing is uncertain; 100–200 million years is a common model estimate."},{zh:"星系与宇宙网",en:"Galaxies & the cosmic web",age:"约 4 亿–100 亿年",ageEn:"~400 million–10 billion years",tag:"GRAVITY WRITES THE STRUCTURE",scale:"星系 → 宇宙网 / GALACTIC",temp:"冷热物质并存",zhText:"星系在引力作用下成长、合并，逐渐组成丝状结构、星系团和空洞交织的宇宙网。",enText:"Galaxies grow and merge under gravity, tracing a cosmic web of filaments, clusters and vast voids.",zhVoice:"恒星汇入星系，星系成长、合并。跨越数十亿年，引力将物质编织成丝状结构和星系团，其间是辽阔的空洞。我们熟悉的旋臂，是后来逐渐形成的风景。",enVoice:"Stars gather in galaxies that grow and merge. Over billions of years, gravity weaves matter into filaments and clusters, separated by vast voids. Familiar spiral arms emerge over time.",note:"跨越数十亿年的缩时示意；成熟旋涡星系不代表最早星系的典型形态。",noteEn:"A time-lapse spanning billions of years. Mature spirals do not represent the earliest galaxies."},{zh:"今天，仍在膨胀",en:"An ever-expanding universe",age:"约 138 亿年",ageEn:"~13.8 billion years",tag:"THE STORY IS STILL UNFOLDING",scale:"可观测宇宙 / OBSERVABLE",temp:"微波背景 2.725 K",zhText:"宇宙在大尺度上加速膨胀，星系群之间的距离继续增长；引力束缚的系统不随之整体膨胀。",enText:"Cosmic expansion accelerates on large scales. Distances between galaxy groups grow, while gravitationally bound systems stay together.",zhVoice:"一百三十八亿年之后，宇宙的故事仍在继续。在最大尺度上，膨胀正在加速。星系之间的广阔空间不断增长，而恒星和星系仍被引力系在一起。我们，也是这段历史的一部分。",enVoice:"After 13.8 billion years, the story continues. On the largest scales, expansion is accelerating. Space between galaxy groups grows, while bound systems stay together. We too are part of this history.",note:"宇宙没有已知的膨胀中心。138亿年是年龄，不是可观测宇宙的半径。",noteEn:"There is no known center of expansion. 13.8 billion years is an age, not the observable universe’s radius."}],kt=26,di=rn.length*kt;const aa="180",yl=0,Ca=1,Tl=2,Oo=1,bl=2,hn=3,Cn=0,Ct=1,dn=2,wn=0,ui=1,Ui=2,Pa=3,Da=4,Al=5,Hn=100,wl=101,Rl=102,Cl=103,Pl=104,Dl=200,Ll=201,Ul=202,Il=203,gs=204,_s=205,Nl=206,Fl=207,Ol=208,Bl=209,zl=210,Hl=211,Vl=212,Gl=213,kl=214,vs=0,xs=1,Ms=2,fi=3,Ss=4,Es=5,ys=6,Ts=7,Bo=0,Wl=1,Xl=2,Rn=0,ql=1,Yl=2,$l=3,Kl=4,Zl=5,jl=6,Jl=7,zo=300,pi=301,mi=302,bs=303,As=304,Ir=306,ws=1e3,Gn=1001,Rs=1002,Kt=1003,Ql=1004,Ji=1005,en=1006,Br=1007,kn=1008,mn=1009,Ho=1010,Vo=1011,Oi=1012,oa=1013,Wn=1014,fn=1015,Wi=1016,la=1017,ca=1018,Bi=1020,Go=35902,ko=35899,Wo=1021,Xo=1022,$t=1023,zi=1026,Hi=1027,qo=1028,ua=1029,Yo=1030,ha=1031,da=1033,Tr=33776,br=33777,Ar=33778,wr=33779,Cs=35840,Ps=35841,Ds=35842,Ls=35843,Us=36196,Is=37492,Ns=37496,Fs=37808,Os=37809,Bs=37810,zs=37811,Hs=37812,Vs=37813,Gs=37814,ks=37815,Ws=37816,Xs=37817,qs=37818,Ys=37819,$s=37820,Ks=37821,Zs=36492,js=36494,Js=36495,Qs=36283,ea=36284,ta=36285,na=36286,ec=3200,tc=3201,nc=0,ic=1,An="",Nt="srgb",gi="srgb-linear",Cr="linear",je="srgb",$n=7680,La=519,rc=512,sc=513,ac=514,$o=515,oc=516,lc=517,cc=518,uc=519,Ua=350